//! The example apps under `examples/apps/`: what `tilo-app examples` lists
//! and `tilo-app new NAME --from-example EXAMPLE` copies.
//!
//! Each example was generated by `tilo-app new` and then rewritten, so its
//! `Cargo.toml`, `tilo-app.toml` and `src/main.rs` are exactly what `new`
//! renders for it; only the files embedded here are the example's own.

use std::path::PathBuf;

use anyhow::{Context, Result, bail};

/// One example app.
#[derive(Debug)]
pub struct Example {
    /// The name `--from-example` takes, and the directory under `examples/apps/`.
    pub name: &'static str,
    /// The one idea the example teaches.
    pub concept: &'static str,
    /// What the app does, in a sentence.
    pub summary: &'static str,
    /// Whether the example uses only what `tilo-app build --platform web`
    /// supports. An example that runs work on a `std::thread` is native-only;
    /// `ui::background` runs everywhere.
    pub web: bool,
    /// Every file of the example other than the ones `new` renders, by path
    /// relative to the app directory.
    pub files: &'static [(&'static str, &'static str)],
}

macro_rules! example_files {
    ($name:literal: $($file:literal),+ $(,)?) => {
        &[$(
            ($file, include_str!(concat!("../../../../examples/apps/", $name, "/", $file))),
        )+]
    };
}

macro_rules! example_files_with_common {
    ($name:literal $(, $file:literal)* $(,)?) => {
        example_files!($name:
            "README.md",
            "locales/en-US.ftl",
            "src/lib.rs",
            "src/locales.rs",
            "tests/app.rs",
            "tests/headless-actions.json",
            $($file,)*
        )
    };
}

