impl Example {
    /// The example called `name`.
    #[must_use]
    pub fn named(name: &str) -> Option<&'static Self> {
        ALL.iter().find(|example| example.name == name)
    }

    /// The package name the example has in the Tilo workspace.
    #[must_use]
    pub fn package_name(&self) -> String {
        format!("example-{}", self.name)
    }

    /// The crate name the example's tests import.
    #[must_use]
    pub fn crate_name(&self) -> String {
        format!("example_{}", self.name.replace('-', "_"))
    }

    /// The example's directory, relative to the checkout root.
    #[must_use]
    pub fn path(&self) -> String {
        format!("examples/apps/{}", self.name)
    }

    fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "name": self.name,
            "concept": self.concept,
            "summary": self.summary,
            "path": self.path(),
            "web": self.web,
        })
    }
}

/// An unknown example name, with the names there are.
pub fn find(name: &str) -> Result<&'static Example> {
    Example::named(name).with_context(|| {
        let names = ALL
            .iter()
            .map(|example| example.name)
            .collect::<Vec<_>>()
            .join(", ");
        format!("there is no example called {name:?}; the examples are {names}")
    })
}

/// Every example, as `tilo-app examples --json` reports them.
#[must_use]
pub fn examples_json() -> serde_json::Value {
    serde_json::Value::Array(ALL.iter().map(Example::to_json).collect())
}

/// One example, optionally with one of its embedded files. No checkout is needed.
///
/// # Errors
/// Unknown example names or paths outside the example's embedded file list.
pub fn details(name: &str, file: Option<&str>) -> Result<serde_json::Value> {
    let example = find(name)?;
    let mut result = serde_json::Map::from_iter([
        ("example".into(), example.to_json()),
        (
            "create_command".into(),
            serde_json::json!(format!("tilo-app new NAME --from-example {name}")),
        ),
    ]);
    if let Some(path) = file {
        let (_, content) = example
            .files
            .iter()
            .find(|(embedded, _)| *embedded == path)
            .with_context(|| {
                let paths = example
                    .files
                    .iter()
                    .map(|(path, _)| *path)
                    .collect::<Vec<_>>()
                    .join(", ");
                format!("the {name} example has no embedded file {path:?}; choose one of: {paths}")
            })?;
        result.insert("file".into(), serde_json::json!(path));
        result.insert("content".into(), serde_json::json!(content));
    } else {
        result.insert(
            "files".into(),
            serde_json::json!(
                example
                    .files
                    .iter()
                    .map(|(path, _)| *path)
                    .collect::<Vec<_>>()
            ),
        );
    }
    Ok(serde_json::Value::Object(result))
}

/// Replace the files `new` rendered for a starter app with the example's,
/// renamed to the new app's identity.
pub(crate) fn overlay(
    rendered: &mut Vec<(PathBuf, String)>,
    example: &Example,
    crate_name: &str,
    app_id: &str,
    title: &str,
) -> Result<()> {
    for (path, source) in example.files {
        let mut source = (*source).to_owned();
        match *path {
            "src/lib.rs" => {
                source = replace_const(&source, "APP_ID", app_id)
                    .with_context(|| format!("the {} example's src/lib.rs", example.name))?;
                source = replace_const(&source, "APP_TITLE", title)
                    .with_context(|| format!("the {} example's src/lib.rs", example.name))?;
            }
            "README.md" => source = retitle_readme(&source, title),
            _ => {}
        }
        let file = std::path::Path::new(path);
        if file.extension().is_some_and(|extension| extension == "rs") {
            source = source.replace(&example.crate_name(), crate_name);
            source = crate::rustfmt_source(&source, file)?;
        }
        let path = PathBuf::from(path);
        match rendered.iter_mut().find(|(rendered, _)| *rendered == path) {
            Some((_, rendered)) => *rendered = source,
            None => rendered.push((path, source)),
        }
    }
    refresh_locale_keys(rendered, example)?;
    Ok(())
}

/// Rewrite the copied app's `src/locales.rs` so its label keys name the
/// messages of its own `locales/en-US.ftl`, which is the app's after the
/// example's files replaced the template's.
fn refresh_locale_keys(rendered: &mut Vec<(PathBuf, String)>, example: &Example) -> Result<()> {
    let source = rendered
        .iter()
        .find(|(path, _)| path == std::path::Path::new("locales/en-US.ftl"))
        .map(|(_, source)| source.clone());
    let Some(source) = source else {
        return Ok(());
    };
    let contract = crate::parse_fluent_catalog(&source)
        .with_context(|| format!("the {} example's locales/en-US.ftl", example.name))?;
    let locales = rendered
        .iter()
        .find(|(path, _)| path == std::path::Path::new("src/locales.rs"))
        .and_then(|(_, registry)| crate::parse_locale_registry(registry).ok());
    let Some(locales) = locales else {
        return Ok(());
    };
    let registry =
        crate::locale_registry_with_keys(&locales, &crate::catalog_message_ids(&contract));
    let path = PathBuf::from("src/locales.rs");
    let registry = crate::rustfmt_source(&registry, &path)?;
    match rendered.iter_mut().find(|(rendered, _)| *rendered == path) {
        Some((_, rendered)) => *rendered = registry,
        None => rendered.push((path, registry)),
    }
    Ok(())
}

fn replace_const(source: &str, name: &str, value: &str) -> Result<String> {
    let prefix = format!("pub const {name}: &str = ");
    let mut replaced = false;
    let lines = source
        .split_inclusive('\n')
        .map(|line| {
            if !replaced && line.starts_with(&prefix) {
                replaced = true;
                format!("{prefix}{value:?};\n")
            } else {
                line.to_owned()
            }
        })
        .collect::<String>();
    if !replaced {
        bail!("no `{prefix}...` line to rename");
    }
    Ok(lines)
}

fn retitle_readme(source: &str, title: &str) -> String {
    match source.split_once('\n') {
        Some((heading, rest)) if heading.starts_with("# ") => format!("# {title}\n{rest}"),
        _ => source.to_owned(),
    }
}
